export function MechanismInteractive(config=presentation.mechanism){return `<div class="eua-mechanism" data-mechanism="${e(config.id)}"><div class="eua-kicker">Механізм · інтерактивна схема</div><h2>${e(config.title)}</h2><p>Фосфокреатин допомагає швидко ресинтезувати ATP з ADP. Фермент — креатинкіназа.</p>${StructureExplorer()}<details class="eua-mechanism-extra"><summary>Графік: спокій, навантаження та відновлення</summary>${PhaseExplorer(config)}</details><details class="eua-mechanism-extra"><summary>Покроково: реакція креатинкінази</summary><h3 class="eua-reaction-label">Окремо: кроки реакції креатинкінази</h3><div class="eua-scene" data-step="use"><svg viewBox="0 0 760 230" role="img" aria-label="Схематичне м’язове волокно з міофібрилами та мітохондрією"><defs><linearGradient id="eua-fiber" x2="0" y2="1"><stop stop-color="#60344f"/><stop offset="1" stop-color="#1c142c"/></linearGradient><linearGradient id="eua-mito"><stop stop-color="#ffb35b"/><stop offset="1" stop-color="#ea6951"/></linearGradient></defs><rect x="15" y="18" width="730" height="190" rx="90" fill="url(#eua-fiber)" stroke="#9a6b8d" stroke-width="2"/><g fill="none" stroke="#c98099" stroke-width="12" opacity=".65"><path d="M85 68H665M70 94H685M60 120H696M70 146H684M87 172H665"/></g><g stroke="#efb1c5" opacity=".5" stroke-width="2"><path d="M160 40V187M200 38V190M260 38V190M300 38V190M360 38V190M400 38V190M460 38V190M500 38V190M560 40V187"/></g><g transform="translate(530 44)"><ellipse cx="55" cy="47" rx="84" ry="36" fill="#291c35" stroke="#ffb35b" stroke-width="3"/><path d="M-3 44q10-48 20 0t20 0t20 0t20 0t20 0t20 0" fill="none" stroke="url(#eua-mito)" stroke-width="5"/></g><text x="48" y="222" fill="#dbc6d4" font-size="14">М’язове волокно · схематично</text><text x="522" y="111" fill="#ffd0a4" font-size="13">Мітохондрія</text><g class="eua-atp-particles" fill="#75e0ff"><circle cx="130" cy="124" r="8"/><circle cx="330" cy="124" r="8"/><circle cx="480" cy="156" r="8"/></g></svg><div class="eua-reaction" aria-label="Оборотна реакція креатинкінази"><div class="eua-molecule eua-pcr"><small>Фосфокреатин</small><strong>PCr</strong><span>+ ADP + H⁺</span></div><div class="eua-enzyme"><span>Креатинкіназа</span><strong aria-hidden="true">⇄</strong></div><div class="eua-molecule eua-atp"><small>Відновлений ATP</small><strong>ATP</strong><span>+ креатин</span></div></div></div><div class="eua-step-copy" aria-live="polite" aria-atomic="true"><span class="eua-kicker" data-step-count>Крок 1 / ${config.steps.length}</span><h3 data-step-title>${e(config.steps[0].title)}</h3><p data-step-text>${e(config.steps[0].text)}</p></div><div class="eua-controls" aria-label="Керування механізмом"><button type="button" data-mechanism-action="previous" aria-label="Попередній крок">← Назад</button><button type="button" data-mechanism-action="play">▶ Відтворити</button><button type="button" data-mechanism-action="pause" disabled>Ⅱ Пауза</button><button type="button" data-mechanism-action="next" aria-label="Наступний крок">Далі →</button><button type="button" data-mechanism-action="reset">↺ Спочатку</button></div></details>${ScientificNote(presentation.notes.mechanism)}<details><summary>Що спрощено та звідки схема</summary><p>${e(config.simplificationNote)}</p><details><summary>Технічна довідка</summary><p>${e(config.id)} · версія ${e(config.version)} · дата попереднього огляду ${date(config.lastReviewed)}</p></details><p>${config.sourceIds.map(id=>link(creatineSources.find(s=>s.id===id).pubmedUrl,'Механізм · '+id)).join(' · ')}</p></details></div>`;}
export function StructureExplorer(config=muscleVisual){const first=config.structures[0];return `<section class="eua-structure-explorer" data-structure-explorer aria-label="Структури м’язового волокна"><div class="eua-structure-layout"><div class="eua-structure-art"><img src="${e(config.image)}" width="1536" height="1024" loading="lazy" alt="Художній розріз скелетного м’язового волокна: паралельні міофібрили, периферичні ядра та мітохондрія. Не мікрофотографія.">${config.structures.map((s,i)=>`<button type="button" data-structure-select="${e(s.id)}" aria-pressed="${i===0}" aria-controls="eua-structure-panel" style="--spot-x:${s.x}%;--spot-y:${s.y}%">${e(s.label)}</button>`).join('')}<span class="eua-art-caption">М’язове волокно · художня ілюстрація</span></div><div class="eua-structure-panel" id="eua-structure-panel"><span class="eua-kicker">Вибери структуру на моделі</span><h3 data-structure-title>${e(first.label)}</h3><div class="eua-structure-tabs" role="group" aria-label="Пояснення структури"><button type="button" data-structure-tab="summary" aria-pressed="true">Що це</button><button type="button" data-structure-tab="detail" aria-pressed="false">Як працює</button><button type="button" data-structure-tab="sources" aria-pressed="false">Джерела</button></div><div data-structure-content aria-live="polite" aria-atomic="true"><p>${e(first.summary)}</p></div>${ScientificNote('Механізм не дорівнює доказу довгострокового приросту сили.')}<a href="#evidence-card">Що показують дослідження у людей ↓</a></div></div><details><summary>Межі ілюстрації та джерела</summary><p>${e(config.simplificationNote)}</p><details><summary>Технічна довідка</summary><p>${e(config.id)} · версія ${e(config.version)} · попередній огляд ${date(config.lastReviewed)}</p></details></details></section>`;}

export function mountStructureExplorer(root,config=muscleVisual){
 if(!root)return;let selected=config.structures[0].id,tab='summary';
 const render=()=>{const s=config.structures.find(s=>s.id===selected);root.querySelector('[data-structure-title]').textContent=s.label;
  root.querySelector('[data-structure-content]').innerHTML=tab==='sources'?`<p>Джерела пояснюють механізм; художнє зображення не є результатом досліду.</p>${config.sourceIds.map(id=>{const source=creatineSources.find(s=>s.id===id);return `<p>${link(source.pubmedUrl,source.shortCitation)}</p>`;}).join('')}`:`<p>${e(s[tab])}</p>`;
  root.querySelectorAll('[data-structure-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.structureSelect===selected)));
  root.querySelectorAll('[data-structure-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.structureTab===tab)));
 };
 root.addEventListener('click',event=>{const structure=event.target.closest('[data-structure-select]'),choice=event.target.closest('[data-structure-tab]');if(structure&&config.structures.some(s=>s.id===structure.dataset.structureSelect)){selected=structure.dataset.structureSelect;render();}if(choice&&['summary','detail','sources'].includes(choice.dataset.structureTab)){tab=choice.dataset.structureTab;render();}});render();
}

export function PhaseExplorer(config=presentation.mechanism){return `<div class="eua-phase-explorer" data-phase-explorer data-phase-state="rest">
 <div class="eua-phase-toolbar"><div><span class="eua-kicker">Спокій → робота → відновлення</span><h3>Побач, як змінюється система</h3></div>
 <div class="eua-level-buttons" role="group" aria-label="Рівень деталізації"><button type="button" data-level-select="simple" aria-pressed="true">Просто</button><button type="button" data-level-select="detailed" aria-pressed="false">Детально</button></div></div>
 <div class="eua-phase-buttons" role="group" aria-label="Фізіологічний стан">${config.phases.map((p,i)=>`<button type="button" data-phase-select="${e(p.id)}" aria-pressed="${i===0}"><span>${i+1}</span>${e(p.label)}</button>`).join('')}</div>
 <div class="eua-phase-graph"><svg viewBox="0 0 760 220" role="img" aria-label="Умовна схема: PCr зменшується під час роботи й відновлюється після; ATP підтримується ресинтезом. Без числової шкали.">
 <rect x="28" y="20" width="704" height="160" rx="12" fill="#0e1b24"/><path d="M48 45H712M48 95H712M48 145H712" stroke="#31424d" stroke-dasharray="4 8"/>
 <path d="M60 60H185C235 60 240 135 350 145H435C510 145 540 60 680 60" fill="none" stroke="#88d9f5" stroke-width="4"/>
 <path d="M60 76H185C280 76 300 91 350 91H435C510 91 570 76 680 76" fill="none" stroke="#f1cb61" stroke-width="3"/>
 <g data-phase-marker><path d="M120 27V170" stroke="#faf8ec" stroke-width="2" stroke-dasharray="5 5"/></g>
 <text x="60" y="207" fill="#b5c8d1" font-size="14">Спокій</text><text x="300" y="207" fill="#b5c8d1" font-size="14">Навантаження</text><text x="580" y="207" fill="#b5c8d1" font-size="14">Відновлення</text>
 </svg><div class="eua-graph-legend"><span>● PCr — умовний запас</span><span>● ATP — підтримується ресинтезом</span></div><p>Якісна схема, не експериментальні криві. Вертикальна позиція й відстані не означають концентрації чи тривалість. За екстремальних умов ATP також може знижуватися.</p></div>
 <div class="eua-phase-copy" aria-live="polite" aria-atomic="true"><h3 data-phase-title>${e(config.phases[0].title)}</h3><p data-phase-description>${e(config.phases[0].description)}</p></div>
 <div class="eua-state-cards"><article><span>Фосфокреатин · PCr</span><strong data-phase-pcr>${e(config.phases[0].pcr)}</strong></article><article><span>ATP</span><strong data-phase-atp>${e(config.phases[0].atp)}</strong></article><article><span>Витрачання ATP</span><strong data-phase-demand>${e(config.phases[0].demand)}</strong></article></div>
 <div class="eua-pathway-map" aria-label="Шляхи ресинтезу ATP"><div class="eua-pathway-pcr"><b>PCr + ADP + H⁺ ⇄ Cr + ATP</b><span>Швидкий буфер · креатинкіназа</span></div><div><b>Гліколіз → ATP</b><span data-phase-glycolysis>${e(config.phases[0].glycolysis)}</span></div><div><b>Мітохондрії → ATP</b><span data-phase-oxphos>${e(config.phases[0].oxphos)}</span></div></div>
 <div class="eua-phase-detail" data-phase-detail hidden><h4>H⁺ та pH</h4><p data-phase-ph>${e(config.phases[0].ph)}</p><h4>Межі цього сценарію</h4><p data-phase-advanced>${e(config.phases[0].detail)}</p><p>Ми не обчислюємо буферну ємність, транспорт протонів, доставку кисню, температуру, pH або ферментну кінетику. До перевіреної числової моделі ці величини не додаються як «реальні» показники.</p></div>
 <div class="eua-phase-provenance"><span>Навчальний сценарій · без персонального прогнозу</span><details><summary>На чому ґрунтується модель?</summary><p>Опубліковані моделі зіставляють PCr, pH та ресинтез ATP із дослідом. Тут показано лише якісну логіку, не їхній числовий розрахунок. Механізм не є доказом приросту сили від добавки.</p>${config.sourceIds.map(id=>{const s=creatineSources.find(s=>s.id===id);return `<p>${link(s.pubmedUrl,s.shortCitation)}</p>`;}).join('')}</details></div>
 </div>`;}

export function mountPhaseExplorer(explorer,config=presentation.mechanism){
 if(!explorer)return;
 const setPhase=id=>{
  const phase=config.phases.find(p=>p.id===id);if(!phase)throw Error('Unknown physiology phase: '+id);
  explorer.dataset.phaseState=id;
  for(const key of ['title','description','pcr','atp','demand','glycolysis','oxphos','ph'])explorer.querySelector(`[data-phase-${key}]`).textContent=phase[key];
  explorer.querySelector('[data-phase-advanced]').textContent=phase.detail;
  explorer.querySelectorAll('[data-phase-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.phaseSelect===id)));
  const marker=explorer.querySelector('[data-phase-marker]');marker.setAttribute('transform',id==='exercise'?'translate(260 0)':id==='recovery'?'translate(540 0)':'translate(0 0)');
 };
 explorer.addEventListener('click',event=>{
  const phase=event.target.closest('[data-phase-select]');if(phase)setPhase(phase.dataset.phaseSelect);
  const level=event.target.closest('[data-level-select]');if(level){const detailed=level.dataset.levelSelect==='detailed';explorer.querySelector('[data-phase-detail]').hidden=!detailed;explorer.querySelectorAll('[data-level-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.levelSelect===level.dataset.levelSelect)));}
 });
 setPhase('rest');
}

export function LastReviewed(module){return `<footer class="eua-reviewed"><div class="eua-kicker">Актуальність Evidence Base</div><p>Дата попереднього огляду: <time datetime="${e(module.lastReviewed)}">${date(module.lastReviewed)}</time></p><p>Evidence version: <b>${e(module.version)}</b> · Статус: <b>${module.evidenceStatus==='reviewing'?'Науковий перегляд триває':e(module.evidenceStatus)}</b></p><p>Оцінки впевненості попередні. Дата не означає завершений систематичний пошук чи фінальне наукове схвалення. Нові публікації не змінюють висновки автоматично.</p></footer>`;}
// 2026-10-22 (owner «А: всі пункти», «креатин коротше»): loading/timing/source and the kidney explanation are folded;
// the simple regimen and a one-line kidney summary stay visible; the duplicate loading button to CLM-000006 is removed.
// Owner request 2026-10-21 («картка креатин»): same layout family as the other dossiers. Order comes from
// creatineModule.sections: hero → effects and safety (short_answer slot, filled by scripts/build-creatine-more.mjs) →
// all Claims as compact cards → dosing → kidneys (+ «Чого ми не стверджуємо») → folded mechanism, myths, sources, PubMed. Scientific wording, confidence and sources of the eight Claims are unchanged.
function CompactClaim(id){const c=getClaim(id);return `<article class="eua-claim bc-claim" data-claim-id="${e(c.id)}"><div class="eua-kicker">${e({efficacy:'Ефект',safety:'Безпека',performance:'Ефект'}[c.claimType]||'Твердження')}</div><h3>${e(presentation.labels[id])}</h3><p class="eua-statement">${e(c.shortStatement)}</p>${ConfidenceBadge(c)}${claimButton(id,'Докази й межі')}</article>`;}
export function renderModule({pubmed=''}={}){
 const m=creatineModule,guidance=presentation.guidance,source=id=>evidenceBase.sources.find(s=>s.id===id);
 // Parts keep the configured section order (creatineModule.sections); the shell only wraps them.
 const order=[];
 const keep=(key,html)=>{order.push(html);return '';};
 return renderEvidenceModule(m,evidenceBase,{
  view:{"short-answer":{"anchorId":"creatine-short","navLabel":"Коротко"},"mechanism":{"anchorId":"creatine-mechanism","navLabel":"Механізм"},"evidence-grid":{"anchorId":"evidence-card","navLabel":"Докази"},"dosing":{"anchorId":"creatine-dosing","navLabel":"Як приймати"},"kidney":{"anchorId":"creatine-kidney","navLabel":"Нирки"},"myths":{"anchorId":"creatine-myths","navLabel":"Міфи"},"sources":{"anchorId":"creatine-sources","navLabel":"Джерела"},"last-reviewed":{"anchorId":"creatine-reviewed","navLabel":"Актуальність"}},
  renderers:{
    hero:()=>`<div class="eua-hero"><div class="eua-kicker">Добавки / навчальний модуль Evidence UA</div><div class="eua-hero-grid"><div><h1>${e(m.title)}<span>.</span></h1><p class="eua-lead">${e(m.subtitle)}</p><p class="cr-lead">Найкраще досліджена дія — більше сили й безжирової маси разом із силовими тренуваннями та кращі повторні короткі зусилля. Витривалість креатин не покращує, а креатинін у крові може трохи зростати без шкоди ниркам.</p></div><div class="base-art eua-hero-art" style="--base-x:0%;--base-y:0%" aria-hidden="true"></div></div><p class="eua-review-banner">Навчальний модуль · попередні оцінки, повний науковий перегляд не завершено</p></div>`,
    short_answer:()=>keep('short','<div id="creatine-short"><!-- CREATINE-MORE:TOP:START --><!-- CREATINE-MORE:TOP:END --></div>'),
    mechanism:()=>keep('mechanism',`<details class="eua-block cr-fold" id="creatine-mechanism"><summary>Як це працює: АТФ і фосфокреатин</summary>${MechanismInteractive()}</details>`),
    evidence_grid:({section})=>keep('claims',`<section class="eua-block" id="evidence-card"><div class="eua-kicker">Що знаємо → наскільки впевнені → чому</div><h2>Твердження й докази</h2><p>Оцінюємо кожне твердження, а не добавку загалом. «Докази й межі» показує конкретні результати й першоджерела.</p><div class="eua-claim-grid bc-claims">${section.claimIds.map(CompactClaim).join('')}</div><details class="cr-notes"><summary>Як читати рівні впевненості й безжирову масу</summary>${ScientificNote(presentation.notes.confidence)}${ScientificNote(presentation.notes.lean)}</details><!-- CREATINE-MORE:CLAIMS:START --><!-- CREATINE-MORE:CLAIMS:END --></section>`),
    dosing:()=>keep('dosing',`<section class="eua-block" id="creatine-dosing"><div class="eua-kicker">Практичні поради · із зазначенням джерел</div><h2>Як приймати</h2><p>${e(guidance.title)}</p><div class="eua-guidance-grid"><article class="eua-guidance"><span>Простий режим</span><h3>${e(guidance.simple)}</h3><p>${e(getClaim('CLM-000006').practicalMeaning||getClaim('CLM-000006').shortStatement)}</p>${claimButton('CLM-000006')}</article></div><details class="cr-notes"><summary>Завантаження, час прийому й джерело</summary><article class="eua-guidance"><span>Швидше насичення · опціонально</span><h3>Фаза завантаження</h3><p>${e(guidance.loading)}</p></article><p>${e(getClaim('CLM-000007').practicalMeaning||getClaim('CLM-000007').shortStatement)}</p>${claimButton('CLM-000007')}<p>${e(guidance.note)}</p><p>${guidance.sourceIds.map(id=>link(source(id).pubmedUrl,'Практичний режим · '+source(id).shortCitation)).join('')}</p></details></section>`),
    kidney:({section})=>keep('kidney',`<section class="eua-block" id="creatine-kidney"><div class="eua-kicker">Два різні питання — окремі висновки</div><h2>Нирки ≠ креатинін</h2><p>Креатинін у крові може трохи зрости, і розрахована фільтрація нирок виглядатиме гіршою — це не те саме, що шкода ниркам.</p><details class="cr-notes"><summary>Як це працює й докази</summary><ol class="eua-kidney-flow">${presentation.kidneyFlow.map(text=>`<li>${e(text)}</li>`).join('')}</ol>${ScientificNote(presentation.notes.kidney)}<div class="eua-actions">${section.claimIds.map(id=>claimButton(id,'Подивитися докази · '+presentation.labels[id])).join('')}</div></details></section><!-- CREATINE-MORE:NOT:START --><!-- CREATINE-MORE:NOT:END -->`),
    myths:()=>keep('myths',`<details class="eua-block cr-fold" id="creatine-myths"><summary>Поширені міфи: що з них правда</summary><div class="eua-myth-grid">${presentation.myths.map(myth=>`<article class="eua-myth"><h3>${e(myth.title)}</h3><p>${e(getClaim(myth.claimIds[0]).shortStatement)}</p><p>${e(getClaim(myth.claimIds[0]).practicalMeaning||'')}</p>${myth.claimIds.map(id=>claimButton(id,'Подивитися докази · '+presentation.labels[id])).join('')}</article>`).join('')}</div>${EvidenceGap('Дані про взаємодію з кофеїном і точний pre/post timing обмежені. Відсутність встановленої переваги — не доказ повної еквівалентності.')}</details>`),
    sources:({sources,base})=>keep('sources',`<details class="eua-block cr-fold" id="creatine-sources"><summary>Наукові джерела</summary><p>Джерела пов’язані з твердженнями через окремі записи результатів досліджень. Метааналізи можуть включати ті самі первинні дослідження — кількість оглядів не дорівнює кількості незалежних доказів.</p><div class="eua-source-grid">${sources.map(s=>SourceCard(s,base.records.filter(r=>r.sourceId===s.id),true,'source',3)).join('')}</div><!-- CREATINE-MORE:SOURCES:START --><!-- CREATINE-MORE:SOURCES:END --></details>`),
    last_reviewed:()=>keep('reviewed',`<details class="eua-block cr-fold cr-pubmed"><summary>Шукати нові дослідження в PubMed</summary>${pubmed}</details><section class="eua-block" id="creatine-reviewed"><details class="cr-fold"><summary>Актуальність і статус перегляду</summary>${LastReviewed(m)}</details><p class="eua-disclaimer">Освітній матеріал, не діагностика й не персональна медична рекомендація.</p><a class="eua-primary home-link" href="#top">← На головну</a></section>`)
  },
  shell:({hero})=>`<section id="creatine" class="eua-module" aria-label="Креатин: структурований огляд доказів">${hero}<div class="eua-content">${order.join('')}</div><dialog id="eua-evidence-dialog" class="eua-dialog" aria-labelledby="eua-drawer-title"><div data-evidence-content></div></dialog></section>`
 });
}

export function mountEvidenceUI(root=document.getElementById('creatine')){if(!root)return;
 mountEvidenceDrawer(root,evidenceBase);
 const widget=root.querySelector('[data-mechanism]'),config=presentation.mechanism;let index=0,timer=null;
 mountPhaseExplorer(root.querySelector('[data-phase-explorer]'),config);
 mountStructureExplorer(root.querySelector('[data-structure-explorer]'));
 const render=()=>{widget.querySelector('[data-step-count]').textContent=`Крок ${index+1} / ${config.steps.length}`;widget.querySelector('[data-step-title]').textContent=config.steps[index].title;widget.querySelector('[data-step-text]').textContent=config.steps[index].text;widget.querySelector('.eua-scene').dataset.step=config.steps[index].active;widget.querySelector('[data-mechanism-action="previous"]').disabled=index===0;widget.querySelector('[data-mechanism-action="next"]').disabled=index===config.steps.length-1;};
 const pause=()=>{if(timer)clearInterval(timer);timer=null;widget.classList.remove('eua-playing');widget.querySelector('[data-mechanism-action="play"]').disabled=false;widget.querySelector('[data-mechanism-action="pause"]').disabled=true;};
 widget.addEventListener('click',event=>{const button=event.target.closest('[data-mechanism-action]');if(!button)return;switch(button.dataset.mechanismAction){case 'play':pause();if(index===config.steps.length-1)index=0;widget.classList.add('eua-playing');button.disabled=true;widget.querySelector('[data-mechanism-action="pause"]').disabled=false;timer=setInterval(()=>{index++;render();if(index===config.steps.length-1)pause();},4500);break;case 'pause':pause();break;case 'next':pause();index=Math.min(index+1,config.steps.length-1);break;case 'previous':pause();index=Math.max(0,index-1);break;case 'reset':pause();index=0;}render();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});window.addEventListener('hashchange',()=>{if(!root.classList.contains('route-active'))pause();});render();
}
if(typeof document!=='undefined')mountEvidenceUI();
